import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] wait = new long[n], keyed = new long[n];
        for (int i = 0; i < n; i++) {
            wait[i] = r.nextLong();
            keyed[i] = wait[i] << 20 | i;  // sort indices by deadline (wait <= 1e9 fits in 43 bits)
        }
        Arrays.sort(keyed);
        boolean[] gone = new boolean[n];
        int head = 0, at = 0, remaining = n;
        long time = 0;
        StringBuilder sb = new StringBuilder();
        while (remaining > 0) {
            while (gone[head]) head++;
            gone[head] = true;  // process the head
            remaining--;
            while (at < n && (keyed[at] >> 20) <= time) {  // drop everything that has expired
                int i = (int) (keyed[at++] & ((1 << 20) - 1));
                if (!gone[i]) { gone[i] = true; remaining--; }
            }
            if (sb.length() > 0) sb.append(' ');
            sb.append(remaining);
            time++;
        }
        System.out.println(sb);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"cmp"
	"os"
	"slices"
	"strconv"
)

func main() {
	n := readInt()
	wait := make([]int, n)
	order := make([]int, n)
	for i := range wait {
		wait[i] = readInt()
		order[i] = i
	}
	slices.SortStableFunc(order, func(i, j int) int { return cmp.Compare(wait[i], wait[j]) })
	alive := make([]bool, n)
	for i := range alive {
		alive[i] = true
	}
	head, at, remaining, time := 0, 0, n, 0
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for remaining > 0 {
		for !alive[head] {
			head++
		}
		alive[head] = false // process the head
		remaining--
		for at < n && wait[order[at]] <= time { // drop everything that has expired
			i := order[at]
			at++
			if alive[i] {
				alive[i] = false
				remaining--
			}
		}
		if time > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(remaining))
		time++
	}
	w.WriteByte('\n')
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
